{"sql": "-- Check all /hr entries
SELECT Salary, 
  TRY_CAST(
    REGEXP_REPLACE(
      REGEXP_REPLACE(
        REGEXP_REPLACE(Salary, '/(yr|mo|hr)', ''),
        ',', '', 'g'
      ),
      '[^0-9.]', ''
    ) AS DOUBLE
  ) AS cleaned_numeric
FROM SalaryDataset 
WHERE Salary LIKE '%/hr'"}
